{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "내담자가 '이기적'이라는 단어를 쉬고 싶은 마음에 붙이고, '뭘 원하는 사람인지도 모르겠다'고 표현하는 것이 '내 욕구보다 남의 욕구가 먼저이며, 나를 앞세우는 것은 이기적인 일이다'라는 핵심 신념이 작동하는 모습과 직접 연결됨. /childhood_data에서 부모가 내담자의 요구에 '이기적이다'라고 핀잔한 경험이 이 신념의 형성 맥락을 보여줌. /situations/3에서 배우자가 '당신은 뭘 원하는지 말을 안 해'라고 했을 때 '내가 원하는 거… 그런 걸 생각해 본 적이 없는 것 같은데'라는 자동사고가 나온 것이 현재 대화의 '뭘 원하는 사람인지도 모르겠다'는 표현과 정확히 같은 패턴."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '쉬고 싶었나 싶기도 한데, 근데 그건 좀 이기적인 생각이잖아요'라고 말한 것이 '내 필요나 힘듦을 앞세우는 것은 이기적이고 부끄러운 일이다'라는 태도가 실시간으로 작동하는 장면. /childhood_data에서 '내 욕구를 내세우는 것은 나쁜 일'이라는 신념이 굳어진 성장 경험이 이 태도의 뿌리."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 아이에게 소리를 지른 뒤 '내가 왜 그랬는지 모르겠어서' 상담을 신청한 것이, 쌓인 피로와 서운함이 가족에게 폭발로 터진 뒤 심한 죄책감을 느끼는 패턴과 일치. /situations/1에서 가족 모임에서 어머니가 내담자에게만 명절 준비를 당연하게 맡기고 남동생은 열외되는 상황이 이런 서운함과 피로를 누적시키는 맥락."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/3"],
      "relevance": "내담자가 '별거 아닌 일이었는데'라고 사건을 축소하고, 상담 신청도 '이런 걸로 시간을 뺏어도 되나' 망설인 것이 자기 상태를 숨기는 패턴과 연결. /situations/3에서 배우자의 질문에 '나는 다 괜찮아'라고 얼버무린 것이 같은 회피 방식."
    }
  ]
}

